new:
// FS-DM-ui：主动给「自己勾的互相关注的人」发私信（设置 → 平台 → 抖音）
Group({ title: "主动私信", aside: dmc.enabled ? Tag(`今天 ${dmSo.todayCount ?? 0} / ${dmc.perDay ?? 2}`, "outline") : null },
	Row({ title: "她主动找这些人聊", desc: "发给谁你说了算：先拉一份「互相关注」名单（希希关注页里显示互相关注的那些），再点掉不想发的。已经有会话的直接发，没有的去对方主页点「私信」现开一个；没选人就一条也不发" },
		dmc.enabled ? Button({ variant: "ghost", disabled: busy || d.enabled !== true || !running, onClick: async () => {
			setBusy(true);
			const r = await api("POST", "/douyin/dm-candidates", {});
			setBusy(false);
			if (!r?.ok) { notify(r?.error ?? "没读到互关名单"); return; }
			setDmCands(r.list ?? []);
			notify(`读到 ${(r.list ?? []).length} 个互相关注的人`);
			refresh();
		} }, "拉互相关注名单") : null,
		dmc.enabled ? Button({ variant: "ghost", disabled: busy || dmPickedList.length === 0 || d.enabled !== true || !running, onClick: () => act("/douyin/dm-now", {}, "发出去了", "没发成") }, "现在试一次") : null,
		sw("她主动找这些人聊", dmc.enabled === true, (v) => save({ dm: { enabled: v } }))),
	dmc.enabled ? Row({ title: "要发给谁", stack: true },
		dmCandList.length === 0
			? Muted("还没拉过名单。点上面的「拉互相关注名单」，从里面点选要发的人。")
			: h("div", { style: { display: "flex", flexWrap: "wrap", gap: "6px" } }, dmCandList.map((x, i) => Button({
				key: `dmc${i}${x.name}`, variant: dmIsPicked(x) ? "secondary" : "ghost", disabled: busy, onClick: () => dmToggle(x)
			}, `${dmIsPicked(x) ? "✓ " : ""}${x.name}`))),
		Muted(dmPickedList.length === 0 ? "一个都没选（她不会发）" : `已选 ${dmPickedList.length} 人：${dmPickedList.map((x) => x.name).join("、")}`)) : null,
	dmc.enabled ? Row({ title: "一天最多发" }, Num({ min: 0, max: 10, "aria-label": "一天最多发几次", ...bind("dmPerDay") }), Muted("次（所有人加起来）")) : null,
	dmc.enabled ? Row({ title: "同一个人隔" }, Num({ min: 1, max: 720, "aria-label": "同一个人隔多少小时", ...bind("dmCoolHours") }), Muted("小时才能再发")) : null,
	dmc.enabled && dmSo.lastError ? Row({ title: "上次出错" }, State("error", dmSo.lastError)) : null,
	dmc.enabled && (dmSo.recent ?? []).length > 0 ? Row({ title: "最近发过", stack: true },
		h("div", { className: "fs-list" }, (dmSo.recent ?? []).map((x, i) => Item({
			key: `d${i}${x.at}`, lead: Tag(x.ok ? "发了" : "没发", x.ok ? undefined : "danger"),
			text: x.text || x.error || "", title: x.text || x.error || "",
			meta: [h("span", { key: "n" }, x.name), h("span", { key: "t" }, relTime(x.at, Date.now()))]
		})))) : null),
